public class Main {
    static int eraseOverlapIntervals(int[][] intervals) {
        int n = intervals.length, bestKept = 0;
        for (int mask = 0; mask < (1 << n); mask++) {          // every subset of intervals
            List<int[]> kept = new ArrayList<>();
            for (int i = 0; i < n; i++) if ((mask & (1 << i)) != 0) kept.add(intervals[i]);
            kept.sort((a, b) -> a[0] - b[0]);
            boolean ok = true;
            for (int i = 1; i < kept.size(); i++) {
                if (kept.get(i)[0] < kept.get(i - 1)[1]) { ok = false; break; }   // overlap found
            }
            if (ok) bestKept = Math.max(bestKept, kept.size());
        }
        return n - bestKept;
    }
}

