#include <bits/stdc++.h>
using namespace std;

int eraseOverlapIntervals(vector<vector<int>>& intervals) {
    int n = intervals.size(), bestKept = 0;
    for (int mask = 0; mask < (1 << n); mask++) {              // every subset of intervals
        vector<vector<int>> kept;
        for (int i = 0; i < n; i++) if (mask & (1 << i)) kept.push_back(intervals[i]);
        sort(kept.begin(), kept.end());
        bool ok = true;
        for (size_t i = 1; i < kept.size(); i++) {
            if (kept[i][0] < kept[i - 1][1]) { ok = false; break; }    // overlap found
        }
        if (ok) bestKept = max(bestKept, (int)kept.size());
    }
    return n - bestKept;
}

