import java.util.*;

public class Main {
    static int eraseOverlapIntervals(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> a[1] - b[1]);   // sort by END time
        int count = 0;
        long end = Long.MIN_VALUE;
        for (int[] iv : intervals) {
            if (iv[0] >= end) {
                end = iv[1];                 // keep this interval, update the tracked end
            } else {
                count++;                       // conflicts, must be removed
            }
        }
        return count;
    }
}

