#include <bits/stdc++.h>
using namespace std;

int eraseOverlapIntervals(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end(), [](auto& a, auto& b) { return a[1] < b[1]; });  // sort by END time
    int count = 0;
    long long end = LLONG_MIN;
    for (auto& iv : intervals) {
        if (iv[0] >= end) {
            end = iv[1];                       // keep this interval, update the tracked end
        } else {
            count++;                             // conflicts, must be removed
        }
    }
    return count;
}
